 const monday=mondayOf(S.currentDate||localDate()),end=dateAdd(monday,6);try{const {data,error}=await sb.from('workout_plans').select('plan_date,exercises,activities').eq('user_id',session.user.id).gte('plan_date',monday).lte('plan_date',end);if(error)throw error;const rows=data||[],legacy=rows.some(r=>(r.exercises||[]).some(e=>/^ex_\d+$/.test(String(e.key||'')))),v22Generated=rows.some(r=>(r.exercises||[]).length&&(r.exercises||[]).every(e=>/^\d{4}-\d{2}-\d{2}_[a-z]+[A-Z]?_\d+$/.test(String(e.key||''))));if(!rows.length||legacy||v22Generated)await persistInitialWeekPlans(S.p,S.currentDate||localDate())}catch(e){console.warn('Não foi possível validar a semana inteligente',e)}
