function renderDateHeader(){const isToday=S.currentDate===localDate();$('#selectedDateLabel').textContent=isToday?'Hoje • '+formatDate(S.currentDate):formatDate(S.currentDate);$('#selectedDateInput').value=S.currentDate;$('#dayEyebrow').textContent=S.dayStatus==='completed'?'DIA CONCLUÍDO':isToday?'HOJE':'REGISTRO DO DIA'}
async function selectDay(date){if(!date)return;S.currentDate=date;await ensureSmartWeekPlans();S.plan=makePlan();S.plan.cal=S.p.calorie_target||S.plan.cal;S.plan.prot=S.p.protein_target||S.plan.prot;S.plan.carb=S.p.carbs_target||S.plan.carb;S.plan.fat=S.p.fat_target||S.plan.fat;S.plan.water=S.p.water_target_l||S.plan.water;hydrateDefaultMeals();await loadDayData();const [{data:h},{data:bh},{data:ah}]=await Promise.all([sb.from('daily_logs').select('*').eq('user_id',session.user.id).order('log_date',{ascending:false}).limit(120),sb.from('beverage_logs').select('*').eq('user_id',session.user.id).order('log_date',{ascending:false}).order('created_at',{ascending:false}).limit(500),sb.from('activity_logs').select('*').eq('user_id',session.user.id).order('log_date',{ascending:false}).limit(500)]);S.history=h||[];S.beverageHistory=bh||[];S.activityHistory=ah||[];await loadEvolutionData();renderApp()}
