function renderEx(){const absent=workoutAbsenceForDate(),activities=Array.isArray(S.plan.activities)?S.plan.activities:[],hasGym=(S.plan.exercises||[]).length>0,total=(S.plan.exercises||[]).length+activities.length;let html=absent?`<article class="item workoutAbsentCard"><div><span>ROTINA NÃO REALIZADA • ${formatDate(S.currentDate)}</span><h3>Você registrou que não realizou o treino de hoje.</h3><p>O registro fica no histórico e o Σ Coach poderá considerar essa ausência na programação.</p></div><button class="soft" onclick="undoGymAbsence()">DESFAZER AUSÊNCIA</button></article>`:'';html+=(S.plan.exercises||[]).map((e,i)=>`<article class="item exerciseCard ${S.ex.has(e.key)?'done':''} ${absent?'absenceMuted':''}"><div class="exerciseInfo"><span>${e.group||'EXERCÍCIO'} • ${formatDate(S.currentDate)}</span><h3>${e.name}</h3><p><b>Músculos:</b> ${e.muscles||e.group||'—'}</p><p>${e.scheme||`${e.sets||3} × ${e.reps||'8–12'}`} • descanso ${e.rest||90}s${e.targetLoad?` • alvo ${e.targetLoad} kg`:''}</p><div class="exerciseActions"><button class="soft mini" onclick="openEditExercise('${e.key}')">EDITAR</button><button class="soft mini" onclick="moveExercise('${e.key}',-1)" ${i===0?'disabled':''}>↑</button><button class="soft mini" onclick="moveExercise('${e.key}',1)" ${i===S.plan.exercises.length-1?'disabled':''}>↓</button></div></div><div class="loadBox"><input id="load_${e.key}" type="number" step="0.5" placeholder="kg" ${absent?'disabled':''}><button class="soft" onclick="saveLoad('${e.key}')" ${absent?'disabled':''}>SALVAR CARGA</button><button class="check" aria-label="Concluir exercício" onclick="togEx('${e.key}')" ${absent?'disabled':''}>${S.ex.has(e.key)?'✓':'○'}</button></div></article>`).join('');html+=activities.map(a=>`<article class="item activityCard integratedActivity ${S.activitiesDone.has(a.key)?'done':''} ${absent?'absenceMuted':''}"><div><span>ATIVIDADE DA ROTINA • ${formatDate(S.currentDate)}</span><h3>${a.name}</h3><p>${a.duration_min?`${a.duration_min} min`:''}${a.notes?` • ${a.notes}`:''}</p></div><button class="check" onclick="togActivity('${a.key}')" ${absent?'disabled':''}>${S.activitiesDone.has(a.key)?'✓':'○'}</button></article>`).join('');if(!total)html+=`<article class="item restDayCard"><div><span>RECUPERAÇÃO • ${formatDate(S.currentDate)}</span><h3>Hoje não há treino programado.</h3><p>Dia livre/recuperação conforme sua rotina semanal atual.</p></div></article>`;html+=`<button class="soft full addExerciseBtn" onclick="openEditExercise()">+ ADICIONAR EXERCÍCIO</button><button class="soft full manageRoutineBtn" onclick="openActivitiesManager()">GERENCIAR ATIVIDADES DA ROTINA</button>${absent||!total?'':`<button class="soft full gymAbsenceBtn" onclick="registerGymAbsence()">${hasGym?'NÃO FUI À ACADEMIA HOJE':'NÃO REALIZEI O TREINO DE HOJE'}</button>`}`;$('#exerciseList').innerHTML=html}
function registerGymAbsence(){if(S.ex.size||S.activitiesDone.size)return toast('Há itens de treino concluídos neste dia. Desmarque-os antes de registrar ausência.');$('#absenceTitle').textContent=(S.plan.exercises||[]).length?'Não fui à academia hoje':'Não realizei o treino de hoje';$('#absenceModal').classList.add('open')}
